{
  "deny-internet": {
    "PreToolUse": [
      {
        "matcher": "search_web|read_url.*|browser_.*",
        "hooks": [
          {
            "type": "command",
            "command": "printf '%s' '{\"decision\":\"deny\",\"reason\":\"Internet access is disabled for this evaluation.\"}'",
            "timeout": 10
          }
        ]
      }
    ]
  }
}

